import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type BitcoinChartProps = Record<string, any>;

const BitcoinLogo: React.FC<{ color: string }> = ({ color }) => (
  <svg width="64" height="64" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="12" cy="12" r="12" fill={color} />
    <path
      d="M16.6 10.6C16.9 9.1 15.8 8.3 14 7.7L14.6 5L13.3 4.7L12.8 7.3C12.4 7.2 12 7.1 11.7 7L12.2 4.3L10.8 4L10.3 6.6C10 6.6 9.7 6.5 9.4 6.4L7 5.8L6.5 7.8C6.5 7.8 7.8 8.1 7.7 8.1C8.4 8.3 8.6 8.8 8.5 9.2L7.5 13.2C7.4 13.5 7.1 13.7 6.6 13.6C6.7 13.6 5.4 13.3 5.4 13.3L4.6 15.4L6.9 16.1C7.2 16.2 7.6 16.3 7.9 16.4L7.4 19L8.7 19.3L9.3 16.7C9.6 16.8 10 16.9 10.3 17L9.8 19.7L11.1 20L11.7 17.3C13.8 17.7 15.5 17.5 16 15.6C16.4 14.1 15.6 13.3 14.4 12.8C15.5 12.5 16.3 11.8 16.6 10.6ZM13.8 14.8C13.4 16.2 11 15.5 9.7 15.2L10.3 12.6C11.6 12.9 14.2 13.3 13.8 14.8ZM14.1 10.4C13.8 11.6 11.9 11 10.8 10.7L11.3 8.4C12.5 8.7 14.5 9.1 14.1 10.4Z"
      fill="white"
    />
  </svg>
);

const BitcoinChart: React.FC<BitcoinChartProps> = ({
  backgroundColor = "#0A0A0C",
  transparentBackground = false,
  durationInSeconds = 10,
  chartColor = "#F7931A",
  startPrice = 65000,
  endPrice = 160000,
  pointsCount = 80,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Memoize all complex path and coordinate calculations
  const {
    points,
    linePath,
    fillPath,
    minPrice,
    maxPrice,
    chartHeight,
    chartBaseY,
    chartWidth,
  } = useMemo(() => {
    const pts = [];
    for (let i = 0; i < pointsCount; i++) {
      const p = i / (pointsCount - 1);
      
      // Smooth accelerating base curve
      const base = startPrice + (endPrice - startPrice) * (p * p * (3 - 2 * p));
      
      // Market noise via sine waves
      const cycle = Math.sin(p * Math.PI * 8);
      const cycle2 = Math.cos(p * Math.PI * 14);
      const noise = base * 0.05 * cycle + base * 0.02 * cycle2;
      
      let value = base + noise;
      if (i === 0) value = startPrice;
      if (i === pointsCount - 1) value = endPrice;
      
      pts.push(value);
    }

    const cWidth = width * 2.5; // Wide enough to allow horizontal panning
    const cHeight = height * 0.45; // Bottom section of the screen
    const cBaseY = height * 0.85; // Ground level for the chart

    const mnPrice = Math.min(...pts) * 0.95;
    const mxPrice = Math.max(...pts) * 1.05;
    const sX = cWidth / (pointsCount - 1);

    const pathCommands = pts.map((p, i) => {
      const x = i * sX;
      const y = cBaseY - ((p - mnPrice) / (mxPrice - mnPrice)) * cHeight;
      return `${i === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`;
    });
    const lPath = pathCommands.join(" ");
    const fPath = `${lPath} L ${cWidth.toFixed(2)} ${cBaseY} L 0 ${cBaseY} Z`;

    return {
      points: pts,
      linePath: lPath,
      fillPath: fPath,
      minPrice: mnPrice,
      maxPrice: mxPrice,
      chartHeight: cHeight,
      chartBaseY: cBaseY,
      chartWidth: cWidth,
    };
  }, [pointsCount, startPrice, endPrice, width, height]);

  // Timing logic
  const totalFrames = Math.max(1, durationInSeconds * fps);
  const drawFrames = Math.floor(totalFrames * 0.85); // Finish drawing before video ends
  
  const easedProgress = interpolate(frame, [0, Math.max(1, drawFrames)], [0, 1], {
    easing: Easing.bezier(0.2, 0.8, 0.2, 1),
    extrapolateRight: "clamp",
  });
  
  const clipWidth = easedProgress * chartWidth;

  // Calculate current price based on the exact path X position
  const currentIndex = (clipWidth / chartWidth) * (pointsCount - 1);
  const iFloor = Math.floor(currentIndex);
  const iCeil = Math.min(pointsCount - 1, Math.ceil(currentIndex));
  const remainder = currentIndex - iFloor;

  const currentPrice = iFloor === iCeil
    ? points[iFloor]
    : points[iFloor] + (points[iCeil] - points[iFloor]) * remainder;

  const dotY = chartBaseY - ((currentPrice - minPrice) / (maxPrice - minPrice)) * chartHeight;

  // Panning logic: keep the head of the chart at focalX once it reaches it
  const focalX = width * 0.6;
  const translateX = clipWidth > focalX ? focalX - clipWidth : 0;

  // Calculate top UI data
  const percentChange = ((currentPrice - startPrice) / startPrice) * 100;
  const isPositive = percentChange >= 0;
  const diffColor = isPositive ? "#00E676" : "#FF1744";
  const diffSymbol = isPositive ? "+" : "";
  const compOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Grid Generation
  const hGridLines = useMemo(() => {
    const lines = [];
    for (let i = 0; i <= 5; i++) {
      const y = chartBaseY - (i / 5) * chartHeight;
      const priceForLine = minPrice + (maxPrice - minPrice) * (i / 5);
      lines.push(
        <g key={`h-${i}`}>
          <line x1={0} y1={y} x2={width} y2={y} stroke="rgba(255,255,255,0.06)" strokeWidth={1.5} strokeDasharray="8 8" />
          <text x={width - 30} y={y - 15} fill="rgba(255,255,255,0.3)" fontSize={22} textAnchor="end" fontFamily={spaceGroteskFamily}>
            ${(priceForLine / 1000).toFixed(0)}k
          </text>
        </g>
      );
    }
    return lines;
  }, [chartBaseY, chartHeight, minPrice, maxPrice, width, spaceGroteskFamily]);

  const xGridLines = useMemo(() => {
    const lines = [];
    const numMonths = 12;
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    for (let i = 0; i < numMonths; i++) {
      const x = (i / (numMonths - 1)) * chartWidth;
      lines.push(
        <g key={`x-${i}`} transform={`translate(${x}, 0)`}>
          <line x1={0} y1={height * 0.35} x2={0} y2={chartBaseY} stroke="rgba(255,255,255,0.06)" strokeWidth={2} />
          <text x={0} y={chartBaseY + 45} fill="rgba(255,255,255,0.3)" fontSize={24} textAnchor="middle" fontFamily={spaceGroteskFamily}>
            {months[i]}
          </text>
        </g>
      );
    }
    return lines;
  }, [chartWidth, height, chartBaseY, spaceGroteskFamily]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        background: transparentBackground
          ? undefined
          : `radial-gradient(circle at 50% 10%, ${backgroundColor} 0%, #000000 100%)`,
        WebkitFontSmoothing: "antialiased",
        opacity: compOpacity,
        transition: "none",
      }}
    >
      {/* Top Header UI */}
      <div
        style={{
          position: "absolute",
          top: "12%",
          left: "8%",
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "24px" }}>
          <BitcoinLogo color={chartColor} />
          <span style={{ fontSize: 48, color: "rgba(255,255,255,0.7)", fontWeight: 600, fontFamily: spaceGroteskFamily }}>
            BTC/USD
          </span>
        </div>
        <div
          style={{
            fontSize: 130,
            color: "#fff",
            fontWeight: 700,
            marginTop: 20,
            fontFamily: spaceGroteskFamily,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          ${currentPrice.toLocaleString("en-US", { maximumFractionDigits: 0 })}
        </div>
        <div
          style={{
            fontSize: 56,
            color: diffColor,
            fontWeight: 600,
            marginTop: 10,
            fontFamily: spaceGroteskFamily,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {diffSymbol}{percentChange.toFixed(2)}%
        </div>
      </div>

      {/* SVG Canvas for Chart & Grids */}
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="15" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
          <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={chartColor} stopOpacity="0.5" />
            <stop offset="100%" stopColor={chartColor} stopOpacity="0.0" />
          </linearGradient>
          <clipPath id="chart-clip">
            <rect x="0" y="0" width={clipWidth} height={height} />
          </clipPath>
        </defs>

        {/* Static Horizontal Grid (Fixed Y-Axis style) */}
        {hGridLines}

        {/* Translating Group for Panning Chart */}
        <g transform={`translate(${translateX}, 0)`}>
          {/* Moving Vertical Grid (X-Axis) */}
          {xGridLines}

          {/* Evolving Chart Lines */}
          <g clipPath="url(#chart-clip)">
            <path d={fillPath} fill="url(#chartGradient)" />
            <path
              d={linePath}
              fill="none"
              stroke={chartColor}
              strokeWidth={8}
              filter="url(#glow)"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d={linePath}
              fill="none"
              stroke="#ffffff"
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </g>

          {/* Current Position Marker */}
          <line
            x1={clipWidth}
            y1={dotY}
            x2={clipWidth}
            y2={chartBaseY}
            stroke="#ffffff"
            strokeWidth={2}
            strokeDasharray="6 6"
            strokeOpacity={0.4}
          />
          <circle cx={clipWidth} cy={dotY} r={16} fill="#fff" filter="url(#glow)" />
          <circle cx={clipWidth} cy={dotY} r={8} fill={chartColor} />

          {/* Floating Pill Label */}
          <g transform={`translate(${clipWidth}, ${dotY})`}>
            <rect x={24} y={-28} width={130} height={56} rx={28} fill={chartColor} filter="url(#glow)" />
            <text
              x={89}
              y={8}
              fill="#000000"
              fontSize={26}
              fontWeight={700}
              textAnchor="middle"
              fontFamily={spaceGroteskFamily}
            >
              ${(currentPrice / 1000).toFixed(1)}k
            </text>
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default BitcoinChart;